import{_ as d,a0 as r,w as u,s as p,ao as a,I as s,x as t,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux","title":"Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限","tag":"201510","desc":""},"relativePath":"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux.md","filePath":"[post].md"}'),l={name:"201510/20151012 Linux FAQs with Answers--How to change USB device permission permanently on Linux.md"};function m(x,e,c,g,S,f){const o=r("Link");return u(),p("div",null,[e[13]||(e[13]=a(`<h1 id="linux-有問必答-如何在-linux-中永久修改-usb-設備權限" tabindex="-1">Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限 <a class="header-anchor" href="#linux-有問必答-如何在-linux-中永久修改-usb-設備權限" aria-label="Permalink to “Linux 有問必答：如何在 Linux 中永久修改 USB 設備權限”">​</a></h1><blockquote><p><strong>提問</strong>：當我嘗試在 Linux 中運行 USB GPS 接收器時我遇到了下面來自 gpsd 的錯誤。</p><pre><code>gpsd[377]: gpsd:ERROR: read-only device open failed: Permission denied
gpsd[377]: gpsd:ERROR: /dev/ttyUSB0: device activation failed.
gpsd[377]: gpsd:ERROR: device open failed: Permission denied - retrying read-only 
</code></pre><p>看上去 gpsd 沒有權限訪問 USB 設備（/dev/ttyUSB0）。我該如何永久修改它在Linux上的權限？</p></blockquote><p>當你在運行一個會讀取或者寫入USB設備的進程時，進程的用户/組必須有權限這麼做才行。當然你可以手動用<code>chmod</code>命令改變 USB 設備的權限，但是手動的權限改變只是暫時的。USB 設備會在下次重啓時恢復它的默認權限。</p><p><img src="https://farm6.staticflickr.com/5741/20848677843_202ff53303_c.jpg" alt=""></p><p>作為一個永久的方式，你可以創建一個基於 udev 的 USB 權限規則，它可以根據你的選擇分配任何權限模式。下面是該如何做。</p><p>首先，你需要找出 USB 設備的 vendorID 和 productID。使用<code>lsusb</code>命令。</p><pre><code>$ lsusb -vvv 
</code></pre><p><img src="https://farm1.staticflickr.com/731/20848677743_39f76eb403_c.jpg" alt=""></p><p>上面<code>lsusb</code>的輸出中，找出你的 USB 設備，並找出&quot;idVendor&quot;和&quot;idProduct&quot;字段。本例中,我們的結果是<code>idVendor (0x067b)</code>和 <code>idProduct (0x2303)</code></p><p>下面創建一個新的udev規則。</p><pre><code>$ sudo vi /etc/udev/rules.d/50-myusb.rules 
</code></pre><hr><pre><code>SUBSYSTEMS==&quot;usb&quot;, ATTRS{idVendor}==&quot;067b&quot;, ATTRS{idProduct}==&quot;2303&quot;, GROUP=&quot;users&quot;, MODE=&quot;0666&quot;
</code></pre><p>用你自己的&quot;idVendor&quot;和&quot;idProduct&quot;來替換。<strong>MODE=&quot;0666&quot;</strong>表示USB設備的權限。</p><p>現在重啓電腦並重新加載 udev 規則：</p><pre><code>$ sudo udevadm control --reload 
</code></pre><p>接着驗證下 USB 設備的權限。</p><p><img src="https://farm1.staticflickr.com/744/21282872179_9a4a05d768_b.jpg" alt=""></p><hr>`,19)),s("p",null,[e[1]||(e[1]=t("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/change-usb-device-permission-linux.html"},{default:i(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/change-usb-device-permission-linux.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...e[2]||(e[2]=[t("Dan Nanni",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:i(()=>[...e[3]||(e[3]=[t("geekpi",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const v=d(l,[["render",m]]);export{B as __pageData,v as default};
